CREATE POLICY published_cover_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='book-covers' AND EXISTS(SELECT 1 FROM public.books WHERE published AND cover_url='storage:'||name));
CREATE POLICY admin_cover_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='book-covers' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_cover_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='book-covers' AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,name text NOT NULL,email text NOT NULL,message text NOT NULL CHECK(length(message) BETWEEN 1 AND 5000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_contact ON public.contact_messages FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid()); CREATE POLICY admin_contact_read ON public.contact_messages FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.reading_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid NOT NULL REFERENCES public.books(id) ON DELETE CASCADE,current_page integer NOT NULL,total_pages integer NOT NULL,category text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reading_history TO authenticated; GRANT ALL ON public.reading_history TO service_role;
ALTER TABLE public.reading_history ENABLE ROW LEVEL SECURITY; CREATE POLICY own_history ON public.reading_history FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.log_reading() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.reading_history(user_id,book_id,current_page,total_pages,category) VALUES(NEW.user_id,NEW.book_id,NEW.current_page,NEW.total_pages,NEW.category); RETURN NEW; END $$;
CREATE TRIGGER reading_history_trigger AFTER INSERT OR UPDATE ON public.reader_shelves FOR EACH ROW EXECUTE FUNCTION public.log_reading();
CREATE TABLE public.activity_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,entity text NOT NULL,entity_id text,action text NOT NULL,changes jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_logs TO authenticated; GRANT ALL ON public.activity_logs TO service_role;
ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY admin_log_read ON public.activity_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_admin_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_logs(actor_id,entity,entity_id,action,changes) VALUES(auth.uid(),TG_TABLE_NAME,coalesce(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'key',to_jsonb(OLD)->>'id'),TG_OP,jsonb_build_object('old',to_jsonb(OLD),'new',to_jsonb(NEW))); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER audit_books AFTER INSERT OR UPDATE OR DELETE ON public.books FOR EACH ROW EXECUTE FUNCTION public.audit_admin_changes();
CREATE TRIGGER audit_events AFTER INSERT OR UPDATE OR DELETE ON public.community_events FOR EACH ROW EXECUTE FUNCTION public.audit_admin_changes();
CREATE TRIGGER audit_settings AFTER INSERT OR UPDATE OR DELETE ON public.community_settings FOR EACH ROW EXECUTE FUNCTION public.audit_admin_changes();
CREATE TRIGGER audit_submissions AFTER UPDATE ON public.author_submissions FOR EACH ROW EXECUTE FUNCTION public.audit_admin_changes();
CREATE FUNCTION public.notify_reply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; BEGIN IF NEW.parent_id IS NOT NULL THEN SELECT user_id INTO recipient FROM public.contributions WHERE id=NEW.parent_id; IF recipient IS NOT NULL AND recipient<>NEW.user_id THEN INSERT INTO public.notifications(user_id,title,body) VALUES(recipient,'A new perspective in your conversation',left(NEW.body,200)); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_reply_trigger AFTER INSERT ON public.contributions FOR EACH ROW EXECUTE FUNCTION public.notify_reply();